import{_ as a,o as s,c as e,a0 as l}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse('{"title":"架构说明","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/reference/architecture.md","filePath":"zh-CN/reference/architecture.md"}'),i={name:"zh-CN/reference/architecture.md"};function p(t,n,o,r,c,d){return s(),e("div",null,[...n[0]||(n[0]=[l(`<h1 id="架构说明" tabindex="-1">架构说明 <a class="header-anchor" href="#架构说明" aria-label="Permalink to &quot;架构说明&quot;">​</a></h1><p>AirlineSim Autobuy 采用管道架构设计，将监控、解析、匹配和执行各阶段分离为独立的模块，通过 Go 的并发原语协同工作。</p><h2 id="架构概览" tabindex="-1">架构概览 <a class="header-anchor" href="#架构概览" aria-label="Permalink to &quot;架构概览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        main.go                             │</span></span>
<span class="line"><span>│  初始化配置 → 创建引擎 → 启动 WebUI → 等待信号              │</span></span>
<span class="line"><span>└──────────┬──────────────────────────────────────────────────┘</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                      Engine                                 │</span></span>
<span class="line"><span>│           监控管道编排器（每个服务器一个 goroutine）           │</span></span>
<span class="line"><span>└──┬──────────┬──────────┬──────────┬──────────┬──────────────┘</span></span>
<span class="line"><span>   │          │          │          │          │</span></span>
<span class="line"><span>   ▼          ▼          ▼          ▼          ▼</span></span>
<span class="line"><span>┌──────┐ ┌──────┐ ┌──────┐ ┌──────┐ ┌──────┐ ┌──────┐</span></span>
<span class="line"><span>│Auth  │ │Client│ │Coll.│ │Pars.│ │Rules│ │Exec.│</span></span>
<span class="line"><span>│认证  │ │HTTP  │ │采集  │ │解析  │ │规则  │ │执行  │</span></span>
<span class="line"><span>│会话  │ │客户端│ │市场  │ │HTML  │ │引擎  │ │购买  │</span></span>
<span class="line"><span>└──────┘ └──────┘ └──────┘ └──────┘ └──────┘ └──────┘</span></span>
<span class="line"><span>                                                       </span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                     WebUI (HTTP Server)                     │</span></span>
<span class="line"><span>│   chi 路由器 → 静态文件服务 (Vue SPA) + REST API           │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="组件概述" tabindex="-1">组件概述 <a class="header-anchor" href="#组件概述" aria-label="Permalink to &quot;组件概述&quot;">​</a></h2><h3 id="_1-入口-cmd-autobuy-main-go" tabindex="-1">1. 入口（cmd/autobuy/main.go） <a class="header-anchor" href="#_1-入口-cmd-autobuy-main-go" aria-label="Permalink to &quot;1. 入口（cmd/autobuy/main.go）&quot;">​</a></h3><p>应用程序的启动点，负责：</p><ul><li>配置日志系统（使用 <code>log/slog</code> 结构化日志）</li><li>确保配置文件存在，若不存在则生成默认配置</li><li>加载配置，初始化配置存储</li><li>创建通知器和引擎实例</li><li>如果启用了 WebUI，启动 HTTP 服务器</li><li>等待系统信号（SIGINT/SIGTERM）实现优雅关闭</li></ul><h3 id="_2-配置管理-internal-config" tabindex="-1">2. 配置管理（internal/config） <a class="header-anchor" href="#_2-配置管理-internal-config" aria-label="Permalink to &quot;2. 配置管理（internal/config）&quot;">​</a></h3><p>配置系统围绕线程安全的 <code>Store</code> 实现：</p><ul><li><strong>Store</strong>：封装了配置的读写操作，使用 <code>sync.RWMutex</code> 保证并发安全</li><li><strong>Watcher</strong>：通过轮询（每 5 秒）监控文件修改时间，实现配置热重载</li><li><strong>类型定义</strong>：<code>Config</code> 结构体映射 YAML 配置的所有字段</li><li><strong>默认配置</strong>：<code>DefaultConfig()</code> 提供合理的默认值</li><li><strong>向后兼容</strong>：自动迁移旧的单服务器/单账户配置到多服务器/多账户格式</li></ul><h3 id="_3-认证模块-internal-auth" tabindex="-1">3. 认证模块（internal/auth） <a class="header-anchor" href="#_3-认证模块-internal-auth" aria-label="Permalink to &quot;3. 认证模块（internal/auth）&quot;">​</a></h3><p>管理与 AirlineSim 游戏服务器的认证会话：</p><ul><li><strong>Session</strong>：封装 HTTP 客户端、Cookie 存储和登录状态</li><li><strong>登录流程</strong>：通过 <code>sar.simulogics.games</code> API 进行密码认证，获取 <code>as-sid</code> 令牌</li><li><strong>会话持久化</strong>：将 Cookie 序列化到本地文件，重启后可恢复</li><li><strong>健康检查</strong>：定期验证会话有效性，过期自动重新登录</li><li><strong>安全传输</strong>：<code>secureTransport</code> 限制只允许连接到已知的游戏服务器域名</li></ul><h3 id="_4-http-客户端-internal-client" tabindex="-1">4. HTTP 客户端（internal/client） <a class="header-anchor" href="#_4-http-客户端-internal-client" aria-label="Permalink to &quot;4. HTTP 客户端（internal/client）&quot;">​</a></h3><p>提供安全的、带限速的 HTTP 客户端：</p><ul><li><strong>速率限制</strong>：基于令牌桶算法，控制请求频率</li><li><strong>随机延迟（Jitter）</strong>：在每次请求前添加随机延迟，模拟人类行为</li><li><strong>自动重试</strong>：遇到服务器错误（5xx）或限流（429）时自动重试最多 3 次</li><li><strong>URL 验证</strong>：严格的安全检查，防止请求到内网地址或恶意域名</li></ul><h3 id="_5-市场采集器-internal-collector" tabindex="-1">5. 市场采集器（internal/collector） <a class="header-anchor" href="#_5-市场采集器-internal-collector" aria-label="Permalink to &quot;5. 市场采集器（internal/collector）&quot;">​</a></h3><p>负责从游戏服务器获取市场页面数据：</p><ul><li><strong>URL 发现</strong>：首次访问时自动发现 Wicket 市场页面的实际 URL</li><li><strong>参数化请求</strong>：支持按飞机系列、型号和排序方式过滤市场数据</li><li><strong>Wicket 兼容</strong>：使用 Wicket 风格的 URL 参数格式</li></ul><h3 id="_6-html-解析器-internal-parser" tabindex="-1">6. HTML 解析器（internal/parser） <a class="header-anchor" href="#_6-html-解析器-internal-parser" aria-label="Permalink to &quot;6. HTML 解析器（internal/parser）&quot;">​</a></h3><p>将 Wicket 市场页面的 HTML 解析为结构化数据：</p><ul><li><strong>HTML 解析</strong>：使用 <code>goquery</code> 库解析 HTML 表格</li><li><strong>字段提取</strong>：从表格行中提取机型、价格、机龄、状态、循环数等信息</li><li><strong>多格式支持</strong>：处理不同地区的数字格式（欧洲格式 <code>1.234.567,89</code> 和美国格式 <code>1,234,567.89</code>）</li><li><strong>交易类型检测</strong>：通过页面内容判断是拍卖还是立即购买</li></ul><h3 id="_7-规则引擎-internal-rules-engine-go" tabindex="-1">7. 规则引擎（internal/rules/engine.go） <a class="header-anchor" href="#_7-规则引擎-internal-rules-engine-go" aria-label="Permalink to &quot;7. 规则引擎（internal/rules/engine.go）&quot;">​</a></h3><p>评估飞机是否符合购买规则并计算评分：</p><ul><li><strong>规则匹配</strong>：依次检查所有启用规则的条件（机型、价格、机龄、状态等）</li><li><strong>评分系统</strong>：综合价格优势、机身状态、机龄、交易类型和规则优先级计算评分</li><li><strong>结果排序</strong>：按评分降序排列，返回最佳匹配</li></ul><h3 id="_8-购买执行器-internal-executor" tabindex="-1">8. 购买执行器（internal/executor） <a class="header-anchor" href="#_8-购买执行器-internal-executor" aria-label="Permalink to &quot;8. 购买执行器（internal/executor）&quot;">​</a></h3><p>执行实际的飞机购买操作：</p><ul><li><strong>立即购买</strong>：访问飞机详情页，提交购买表单</li><li><strong>竞拍出价</strong>：提交竞拍出价，支持自定义加价幅度</li><li><strong>余额检查</strong>：在购买前检查最低余额保护</li><li><strong>价格验证</strong>：验证当前价格是否与预期一致</li></ul><h3 id="_9-通知器-internal-notifier" tabindex="-1">9. 通知器（internal/notifier） <a class="header-anchor" href="#_9-通知器-internal-notifier" aria-label="Permalink to &quot;9. 通知器（internal/notifier）&quot;">​</a></h3><p>通过配置的渠道发送事件通知：</p><ul><li><strong>控制台输出</strong>：使用 <code>slog</code> 输出带表情符号的结构化日志</li><li><strong>Discord Webhook</strong>：支持通过 Webhook 发送通知到 Discord 频道</li><li><strong>事件类型</strong>：发现飞机、购买成功、购买失败、出价成功、错误、信息</li></ul><h3 id="_10-web-管理界面-internal-webui" tabindex="-1">10. Web 管理界面（internal/webui） <a class="header-anchor" href="#_10-web-管理界面-internal-webui" aria-label="Permalink to &quot;10. Web 管理界面（internal/webui）&quot;">​</a></h3><p>提供基于 Web 的图形化管理界面：</p><ul><li><strong>HTTP 服务器</strong>：使用 <code>chi</code> 路由库</li><li><strong>REST API</strong>：提供完整的 REST API 用于引擎控制和配置管理</li><li><strong>静态文件服务</strong>：嵌入 Vue 3 单页应用，非 API 路由全部回退到 <code>index.html</code></li><li><strong>CORS 支持</strong>：开发模式下允许跨域请求</li></ul><h2 id="数据流" tabindex="-1">数据流 <a class="header-anchor" href="#数据流" aria-label="Permalink to &quot;数据流&quot;">​</a></h2><p>以下是单次市场扫描周期的数据流：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 定时器触发 ──→ Engine.runServerCycle()</span></span>
<span class="line"><span>                      │</span></span>
<span class="line"><span>2. 检查会话健康 ──→ Session.HealthCheck()</span></span>
<span class="line"><span>                      │ 如果过期则重新登录</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>3. 构建过滤参数 ──→ 读取第一条启用规则的过滤条件</span></span>
<span class="line"><span>                      │</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>4. 获取市场页面 ──→ Collector.Fetch(filterParams)</span></span>
<span class="line"><span>                      │</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>5. 解析 HTML ────→ Parser.Parse(html)</span></span>
<span class="line"><span>                      │ 返回 AircraftOffer 列表</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>6. 去重检查 ──────→ 使用 seen map 检查是否已处理过</span></span>
<span class="line"><span>                      │</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>7. 规则匹配 ──────→ RulesEngine.Evaluate(aircraft)</span></span>
<span class="line"><span>                      │ 返回 MatchResult 列表</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>8. 执行购买 ──────→ Executor.Execute(request)</span></span>
<span class="line"><span>                      │ 立即购买或竞拍出价</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>9. 发送通知 ──────→ Notifier.Notify(event)</span></span>
<span class="line"><span>                      │ 控制台和/或 Discord</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>10. 更新状态 ─────→ 更新 ServerStatus 统计</span></span></code></pre></div><h2 id="并发模型" tabindex="-1">并发模型 <a class="header-anchor" href="#并发模型" aria-label="Permalink to &quot;并发模型&quot;">​</a></h2><p>程序使用 Go 的 goroutine 和 channel 实现并发：</p><h3 id="引擎并发" tabindex="-1">引擎并发 <a class="header-anchor" href="#引擎并发" aria-label="Permalink to &quot;引擎并发&quot;">​</a></h3><ul><li>每个配置的服务器在独立的 goroutine 中运行（<code>Engine.runServerLoop</code>）</li><li>所有服务器共享同一个配置存储和规则引擎</li><li>引擎停止时通过 <code>context.Context</code> 的取消函数通知所有 goroutine 退出</li></ul><h3 id="数据同步" tabindex="-1">数据同步 <a class="header-anchor" href="#数据同步" aria-label="Permalink to &quot;数据同步&quot;">​</a></h3><ul><li>配置存储使用 <code>sync.RWMutex</code> 保护读写</li><li>引擎状态使用 <code>sync.RWMutex</code> 保护</li><li>已处理飞机 ID 使用 <code>seen map</code> 配合互斥锁去重</li><li>每个服务器使用独立的 <code>serverRunner</code> 实例，避免共享状态</li></ul><h3 id="速率控制" tabindex="-1">速率控制 <a class="header-anchor" href="#速率控制" aria-label="Permalink to &quot;速率控制&quot;">​</a></h3><ul><li>HTTP 客户端使用令牌桶模式限制请求频率</li><li>每个服务器独立控制请求速率</li><li>随机延迟（Jitter）防止请求模式被检测</li></ul><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>airlinesim-autobuy/</span></span>
<span class="line"><span>├── cmd/autobuy/          # 应用程序入口</span></span>
<span class="line"><span>│   └── main.go</span></span>
<span class="line"><span>├── internal/</span></span>
<span class="line"><span>│   ├── auth/             # 认证与会话管理</span></span>
<span class="line"><span>│   │   └── auth.go</span></span>
<span class="line"><span>│   ├── client/           # 限速 HTTP 客户端</span></span>
<span class="line"><span>│   │   └── client.go</span></span>
<span class="line"><span>│   ├── collector/        # 市场数据采集</span></span>
<span class="line"><span>│   │   └── collector.go</span></span>
<span class="line"><span>│   ├── config/           # 配置管理与热重载</span></span>
<span class="line"><span>│   │   ├── config.go</span></span>
<span class="line"><span>│   │   ├── types.go</span></span>
<span class="line"><span>│   │   └── watcher.go</span></span>
<span class="line"><span>│   ├── engine/           # 管道编排</span></span>
<span class="line"><span>│   │   └── engine.go</span></span>
<span class="line"><span>│   ├── executor/         # 购买执行</span></span>
<span class="line"><span>│   │   └── executor.go</span></span>
<span class="line"><span>│   ├── marketdata/       # 飞机市场参考数据</span></span>
<span class="line"><span>│   │   └── data.go</span></span>
<span class="line"><span>│   ├── notifier/         # 通知系统</span></span>
<span class="line"><span>│   │   └── notifier.go</span></span>
<span class="line"><span>│   ├── parser/           # HTML 页面解析</span></span>
<span class="line"><span>│   │   └── parser.go</span></span>
<span class="line"><span>│   ├── rules/            # 规则引擎</span></span>
<span class="line"><span>│   │   └── engine.go</span></span>
<span class="line"><span>│   └── webui/            # Web 管理界面</span></span>
<span class="line"><span>│       ├── server.go</span></span>
<span class="line"><span>│       └── frontend/     # Vue 3 前端源码</span></span>
<span class="line"><span>├── configs/              # 配置文件目录</span></span>
<span class="line"><span>├── docs/                 # VitePress 文档</span></span>
<span class="line"><span>├── Makefile</span></span>
<span class="line"><span>└── go.mod</span></span></code></pre></div>`,48)])])}const g=a(i,[["render",p]]);export{h as __pageData,g as default};
